// CUSTOM business metrics exported to Prometheus via Micrometer
package com.bank.risk.metrics;

import io.micrometer.core.instrument.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import java.util.concurrent.atomic.AtomicInteger;

@Component
@Slf4j
public class RiskMetricsService {

    private final Counter assessmentCounter;
    private final Counter highRiskCounter;
    private final Timer assessmentTimer;
    private final AtomicInteger activeAssessments;

    public RiskMetricsService(MeterRegistry registry) {
        // Counter: total assessments performed
        this.assessmentCounter = Counter.builder("risk.assessments.total")
            .description("Total risk assessments performed")
            .tag("service", "risk-monitoring")
            .register(registry);

        // Counter: high-risk detections
        this.highRiskCounter = Counter.builder("risk.assessments.high_risk")
            .description("High-risk assessments detected")
            .register(registry);

        // Timer: assessment duration
        this.assessmentTimer = Timer.builder("risk.assessment.duration")
            .description("Risk assessment processing time")
            .register(registry);

        // Gauge: currently active assessments
        this.activeAssessments = new AtomicInteger(0);
        Gauge.builder("risk.assessments.active", activeAssessments, AtomicInteger::get)
            .description("Currently active assessments")
            .register(registry);
    }

    public void recordAssessment() { assessmentCounter.increment(); }
    public void recordHighRisk() { highRiskCounter.increment(); }
    public Timer.Sample startTimer() { return Timer.start(); }
    public void stopTimer(Timer.Sample sample) { sample.stop(assessmentTimer); }
    public void incrementActive() { activeAssessments.incrementAndGet(); }
    public void decrementActive() { activeAssessments.decrementAndGet(); }
}
