package com.bank.risk.service;

import com.bank.risk.dto.*;
import com.bank.risk.metrics.RiskMetricsService;
import com.bank.risk.model.RiskScore;
import io.micrometer.core.instrument.Timer;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import jakarta.persistence.EntityManager;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class RiskAssessmentService {

    private final EntityManager entityManager;
    private final RiskMetricsService metrics;

    @Transactional
    public RiskResponse assess(RiskRequest request) {
        Timer.Sample timerSample = metrics.startTimer();
        metrics.incrementActive();

        try {
            log.info("Assessing risk for account {}", request.accountId());

            // Simulated ML scoring (real app calls ML model)
            int score = calculateScore(request.accountId());
            String level = score >= 80 ? "HIGH" : score >= 50 ? "MEDIUM" : "LOW";

            // Persist assessment
            RiskScore riskScore = new RiskScore(request.accountId(), score, level);
            entityManager.persist(riskScore);

            // Record metrics
            metrics.recordAssessment();
            if ("HIGH".equals(level)) {
                metrics.recordHighRisk();
                log.warn("HIGH RISK detected for account {}: score={}", request.accountId(), score);
            }

            long elapsed = metrics.stopTimer(timerSample) != null ? 0 : 0;
            metrics.stopTimer(timerSample);

            return new RiskResponse(request.accountId(), score, level, 0);
        } finally {
            metrics.decrementActive();
        }
    }

    private int calculateScore(String accountId) {
        // Simulated — real app uses ML model
        return (int) (Math.random() * 100);
    }
}
