    @Mock RiskMetricsService metrics;
    @InjectMocks RiskAssessmentService riskService;

    @Test
    void shouldAssessRiskAndRecordMetrics() {
        when(metrics.startTimer()).thenReturn(mock(Timer.Sample.class));

        RiskResponse response = riskService.assess(new RiskRequest("SAV2001"));

        assertThat(response.accountId()).isEqualTo("SAV2001");
